// ANN benchmark over real text embeddings generated by Ollama.
// The source corpus is deterministic; every vector is produced by nomic-embed-text.
#define main vectorforge_server_entrypoint
#include "../main.cpp"
#undef main

#include <numeric>

struct EmbeddingCorpus {
    std::vector<std::vector<float>> documents;
    std::vector<std::vector<float>> queries;
    int dimensions = 0;
};

static EmbeddingCorpus loadCorpus(const std::string& path) {
    std::ifstream input(path, std::ios::binary);
    if (!input) throw std::runtime_error("Cannot open embedding corpus: " + path);
    uint32_t documentCount = 0, queryCount = 0, dimensions = 0;
    input.read(reinterpret_cast<char*>(&documentCount), sizeof(documentCount));
    input.read(reinterpret_cast<char*>(&queryCount), sizeof(queryCount));
    input.read(reinterpret_cast<char*>(&dimensions), sizeof(dimensions));
    if (!input || documentCount < 10000 || queryCount < 100 || dimensions == 0 || dimensions > 8192)
        throw std::runtime_error("Invalid embedding corpus header or insufficient vectors");

    EmbeddingCorpus corpus;
    corpus.dimensions = static_cast<int>(dimensions);
    auto readVectors = [&](uint32_t count, std::vector<std::vector<float>>& destination) {
        destination.reserve(count);
        for (uint32_t i = 0; i < count; ++i) {
            std::vector<float> vector(dimensions);
            input.read(reinterpret_cast<char*>(vector.data()),
                       static_cast<std::streamsize>(dimensions * sizeof(float)));
            if (!input) throw std::runtime_error("Embedding corpus is truncated");
            destination.push_back(std::move(vector));
        }
    };
    readVectors(documentCount, corpus.documents);
    readVectors(queryCount, corpus.queries);
    return corpus;
}

static double mean(const std::vector<double>& values) {
    if (values.empty()) return 0.0;
    return std::accumulate(values.begin(), values.end(), 0.0) / values.size();
}

int main(int argc, char** argv) {
    if (argc != 2) {
        std::cerr << "Usage: ann-benchmark <ollama-embedding-corpus.bin>\n";
        return 1;
    }

    try {
        const auto corpus = loadCorpus(argv[1]);
        constexpr int K = 10;
        constexpr int QUERY_COUNT = 100;
        const std::vector<int> sizes = {1000, 5000, 10000};
        if (static_cast<int>(corpus.queries.size()) < QUERY_COUNT)
            throw std::runtime_error("At least 100 query embeddings are required");

        std::cout << "dataset_size,dimensions,build_ms,queries,k,hnsw_recall_at_10,"
                     "bruteforce_avg_us,kdtree_cosine_avg_us,hnsw_avg_us\n";

        for (int n : sizes) {
            BruteForce brute;
            KDTree kd(corpus.dimensions);
            HNSW hnsw(16, 200);
            std::vector<VectorItem> items;
            items.reserve(n);

            auto buildStart = std::chrono::steady_clock::now();
            for (int i = 0; i < n; ++i) {
                VectorItem item{i + 1, "ollama-embedding", "text-corpus",
                                corpus.documents[static_cast<size_t>(i)]};
                items.push_back(item);
                brute.insert(item);
                kd.insert(item);
                hnsw.insert(item, cosine);
            }
            const double buildMs = std::chrono::duration<double, std::milli>(
                std::chrono::steady_clock::now() - buildStart).count();

            std::vector<double> bfTimes, kdTimes, hnswTimes;
            int relevantFound = 0;
            for (int qi = 0; qi < QUERY_COUNT; ++qi) {
                const auto& q = corpus.queries[static_cast<size_t>(qi)];
                auto timed = [](auto&& fn, std::vector<std::pair<float,int>>& out) {
                    const auto start = std::chrono::steady_clock::now();
                    out = fn();
                    return std::chrono::duration<double, std::micro>(
                        std::chrono::steady_clock::now() - start).count();
                };

                std::vector<std::pair<float,int>> exact, kdResult, ann;
                bfTimes.push_back(timed([&]{ return brute.knn(q, K, cosine); }, exact));
                kdTimes.push_back(timed([&]{ return kd.knn(q, K, cosine, false); }, kdResult));
                hnswTimes.push_back(timed([&]{ return hnsw.knn(q, K, 50, cosine); }, ann));

                std::set<int> exactIds;
                for (const auto& hit : exact) exactIds.insert(hit.second);
                for (const auto& hit : ann)
                    if (exactIds.count(hit.second)) ++relevantFound;

                if (kdResult.size() != exact.size()) {
                    std::cerr << "KD-Tree returned a different result count at N=" << n << "\n";
                    return 2;
                }
                for (size_t i = 0; i < exact.size(); ++i) {
                    if (exact[i].second != kdResult[i].second ||
                        std::abs(exact[i].first - kdResult[i].first) > 1e-5f) {
                        std::cerr << "KD-Tree cosine exactness mismatch at N=" << n << "\n";
                        return 3;
                    }
                }
            }

            const double recall = static_cast<double>(relevantFound) /
                                  (QUERY_COUNT * K);
            std::cout << n << ',' << corpus.dimensions << ','
                      << std::fixed << std::setprecision(2) << buildMs
                      << ',' << QUERY_COUNT << ',' << K << ','
                      << std::setprecision(4) << recall << ','
                      << std::setprecision(2) << mean(bfTimes) << ','
                      << mean(kdTimes) << ',' << mean(hnswTimes) << '\n';
        }
    } catch (const std::exception& error) {
        std::cerr << "ANN benchmark failed: " << error.what() << '\n';
        return 1;
    }
    return 0;
}
